// ── Validate required fields ────────────────────────────────────────────────
const body = $input.first().json.body ?? $input.first().json;

const REQUIRED = ['contact_id', 'name', 'phone', 'requested_start', 'requested_end'];
const missing  = REQUIRED.filter(k => !body[k]?.toString().trim());
if (missing.length > 0) {
  return [{ json: {
    _error:          true,
    status:          'error',
    trace_id:        body.trace_id ?? 'unknown',
    idempotency_key: '',
    message:         'Champs requis manquants: ' + missing.join(', '),
  }}];
}

// ── Normalise ────────────────────────────────────────────────────────────────
const trace_id        = body.trace_id ?? Math.random().toString(36).slice(2, 8);
const idempotency_key = `${body.contact_id}::${body.requested_start}`;

return [{ json: {
  _error:           false,
  trace_id,
  idempotency_key,
  contact_id:       body.contact_id,
  name:             body.name,
  phone:            body.phone,
  email:            body.email       ?? null,
  requested_start:  body.requested_start,
  requested_end:    body.requested_end,
  timezone:         body.timezone    ?? 'Europe/Paris',
}}];

// ── Idempotency guard (n8n static workflow data) ─────────────────────────────
// Static data persists across executions on self-hosted n8n.
// TTL de 7 jours : on nettoie les entrées > 7 jours.
const staticData      = $getWorkflowStaticData('global');
const key             = $input.first().json.idempotency_key;
const now             = Date.now();
const TTL_MS          = 7 * 24 * 60 * 60 * 1000;

// Purge expired keys
for (const k of Object.keys(staticData)) {
  if (now - (staticData[k] ?? 0) > TTL_MS) delete staticData[k];
}

// Check — clé déjà traitée → NOOP, pas de double sync ni double message
if (staticData[key]) {
  return [{ json: {
    _noop:           true,
    status:          'noop',
    trace_id:        $input.first().json.trace_id,
    idempotency_key: key,
    message:         'Déjà traité — clé: ' + key,
  }}];
}

// Mark as processed
staticData[key] = now;

return [{ json: {
  _noop:           false,
  ...$input.first().json,
}}];

// ── Parse FreeBusy response + generate alternatives ─────────────────────────
const freeBusyResp = $input.first().json;
const booking      = $('Is Noop?').first().json;

const calId   = $env.GOOGLE_CALENDAR_ID;
const busyArr = freeBusyResp?.calendars?.[calId]?.busy ?? [];
const isBusy  = busyArr.length > 0;

// Durée du créneau demandé (en ms)
const durationMs = new Date(booking.requested_end).getTime() - new Date(booking.requested_start).getTime();

// Propose 2 alternatives : +1h et +2h depuis requested_start
function makeAlt(hours) {
  const start = new Date(new Date(booking.requested_start).getTime() + hours * 3600000);
  const end   = new Date(start.getTime() + durationMs);
  return { start: start.toISOString(), end: end.toISOString() };
}

const alternatives = isBusy ? [ makeAlt(1), makeAlt(2) ] : [];

return [{ json: {
  ...booking,
  _conflict:    isBusy,
  busy_slots:   busyArr,
  alternatives,
}}];

// ── Build booked output — passe la donnée vers step 3 ────────────────────────
const eventResp = $input.first().json;
const booking   = $('Parse FreeBusy').first().json;

return [{ json: {
  status:              'booked',
  trace_id:            booking.trace_id,
  idempotency_key:     booking.idempotency_key,
  contact_id:          booking.contact_id,
  name:                booking.name,
  phone:               booking.phone,
  email:               booking.email,
  timezone:            booking.timezone ?? 'Europe/Paris',
  requested_start:     booking.requested_start,
  requested_end:       booking.requested_end,
  calendar_event_id:   eventResp.id            ?? null,
  calendar_event_link: eventResp.htmlLink       ?? null,
  summary:             eventResp.summary        ?? null,
  start:               eventResp.start?.dateTime ?? booking.requested_start,
  end:                 eventResp.end?.dateTime   ?? booking.requested_end,
}}];

// ── Step 3 — GHL Sync Prep + format confirmation messages ────────────────────
const b = $input.first().json;

// Format date/heure lisible en Europe/Paris
const startDt  = new Date(b.start ?? b.requested_start);
const tz       = 'Europe/Paris';

const dateStr  = startDt.toLocaleDateString('fr-FR', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', timeZone: tz
});
const timeStr  = startDt.toLocaleTimeString('fr-FR', {
  hour: '2-digit', minute: '2-digit', timeZone: tz
});

// Note GHL — récap complet pour historique contact
const noteBody = [
  '✅ RDV confirmé — [QOS][DEMO]',
  'Date : ' + dateStr + ' à ' + timeStr + ' (' + tz + ')',
  'Google Event ID : ' + (b.calendar_event_id ?? 'N/A'),
  'Lien calendrier : ' + (b.calendar_event_link ?? 'N/A'),
  'trace_id : ' + b.trace_id,
  'contact_id : ' + b.contact_id,
].join('\n');

// SMS/WhatsApp confirmation client
const firstName = ((b.name ?? '').split(' ')[0]) || (b.name ?? 'Client');
const msgBody   = [
  'Bonjour ' + firstName + ',',
  '',
  'Votre RDV de qualification est confirmé ✅',
  '📅 ' + dateStr,
  '⏰ ' + timeStr + ' (heure de Paris)',
  '',
  'Pour replanifier, répondez REPLANIFIER.',
  '— Lucie, Qorpo IA',
].join('\n');

return [{ json: {
  ...b,
  _date_str:       dateStr,
  _time_str:       timeStr,
  _ghl_note_body:  noteBody,
  _ghl_sms_body:   msgBody,
  _ghl_key_set:    !!(($env.GHL_API_KEY ?? '').trim()),
}}];

// ── Internal Log + alert detection ──────────────────────────────────────────
const b        = $('GHL Sync Prep').first().json;
const noteResp = (() => { try { return $('GHL Add Note').first().json; }          catch(e) { return {}; } })();
const smsResp  = (() => { try { return $('GHL Send Confirmation').first().json;  } catch(e) { return {}; } })();
const waResp   = (() => { try { return $('GHL WhatsApp Fallback').first().json;  } catch(e) { return {}; } })();

const ghlNoteOk = !!(noteResp?.id) && !(noteResp?.error);
const ghlSmsOk  = !!(smsResp?.messageId || smsResp?.id || smsResp?.conversationId) && !(smsResp?.error);
const ghlWaOk   = !!(waResp?.messageId  || waResp?.id  || waResp?.conversationId)  && !(waResp?.error);
const ghlMsgOk  = ghlSmsOk || ghlWaOk;

const alertNeeded = !ghlNoteOk || !ghlMsgOk;

const alertPayload = alertNeeded ? {
  event:      'booking_alert',
  trace_id:   b.trace_id,
  contact_id: b.contact_id,
  flags: {
    ghl_note_ok: ghlNoteOk,
    ghl_sms_ok:  ghlSmsOk,
    ghl_wa_ok:   ghlWaOk,
    ghl_key_set: b._ghl_key_set,
  },
  ts: new Date().toISOString(),
} : null;

return [{ json: {
  status:              'confirmed',
  trace_id:            b.trace_id,
  idempotency_key:     b.idempotency_key,
  contact_id:          b.contact_id,
  calendar_event_id:   b.calendar_event_id,
  calendar_event_link: b.calendar_event_link,
  start:               b.start,
  end:                 b.end,
  ghl_sync:            ghlNoteOk ? 'done' : 'partial',
  ghl_note_ok:         ghlNoteOk,
  ghl_sms_ok:          ghlSmsOk,
  ghl_wa_ok:           ghlWaOk,
  _alert_needed:       alertNeeded,
  _alert_payload:      alertPayload,
  _internal_log: {
    event:             'booking_confirmed',
    trace_id:          b.trace_id,
    contact_id:        b.contact_id,
    calendar_event_id: b.calendar_event_id,
    ghl_note_ok:       ghlNoteOk,
    ghl_sms_ok:        ghlSmsOk,
    ghl_wa_ok:         ghlWaOk,
    rdv_date:          b._date_str,
    rdv_time:          b._time_str,
    ts:                new Date().toISOString(),
  },
}}];

// ── Build final response — toujours lu depuis Internal Log ──────────────────
const d = $('Internal Log').first().json;
return [{ json: {
  status:              d.status,
  trace_id:            d.trace_id,
  idempotency_key:     d.idempotency_key,
  calendar_event_id:   d.calendar_event_id,
  calendar_event_link: d.calendar_event_link,
  start:               d.start,
  end:                 d.end,
  ghl_sync:            d.ghl_sync,
}}];
